<?php

namespace Database\Seeders;

use App\Models\NewsCategory;
use App\Models\NewsPost;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

/**
 * 50+ demo কৃষি সংবাদ articles across 15 categories.
 *
 * Idempotent: categories firstOrCreate by slug, articles updateOrCreate by slug.
 * Every article references a real image in public/images/news/ (served without a
 * storage symlink) and is flagged is_demo. Real/manual news is never touched.
 */
class AgricultureNewsSeeder extends Seeder
{
    public function run(): void
    {
        $categories = [
            'weather-alert' => 'আবহাওয়া',
            'government-circular' => 'সরকারি ঘোষণা',
            'agriculture-news' => 'কৃষি সংবাদ',
            'agri-tech' => 'কৃষি প্রযুক্তি',
            'crops' => 'ফসল',
            'seeds-news' => 'বীজ',
            'fertilizer-update' => 'সার',
            'machinery-news' => 'কৃষি যন্ত্রপাতি',
            'pesticide-news' => 'কৃষি ঔষধ',
            'market-update' => 'বাজার দর',
            'livestock-news' => 'প্রাণিসম্পদ',
            'fisheries' => 'মৎস্য',
            'success-story' => 'সফল কৃষকের গল্প',
            'agri-advice' => 'কৃষি পরামর্শ',
            'training' => 'প্রশিক্ষণ ও কর্মশালা',
        ];

        $catId = [];
        foreach ($categories as $slug => $name) {
            $catId[$slug] = NewsCategory::firstOrCreate(['slug' => $slug], ['name' => $name])->id;
        }

        foreach ($this->articles() as $idx => $a) {
            $slug = 'demo-' . Str::lower(Str::random(4)) . '-' . ($idx + 1);
            // Stable slug per title so re-runs update the same row.
            $existing = NewsPost::where('title', $a['t'])->where('is_demo', true)->first();

            NewsPost::updateOrCreate(
                ['title' => $a['t'], 'is_demo' => true],
                [
                    'category_id' => $catId[$a['cat']] ?? null,
                    'slug' => $existing->slug ?? $slug,
                    'description' => $a['s'],
                    'content' => $a['c'],
                    'image' => 'images/news/' . $a['img'] . '.jpg',
                    'district' => null,
                    'is_important' => $a['feat'] ?? false,
                    'views_count' => rand(35, 1200),
                    'status' => 'published',
                    'published_at' => now()->subDays(rand(0, 59))->subHours(rand(0, 23)),
                ]
            );
        }
    }

